//! Checks against reference solutions: each problem formulated independently in CVXPY, and the
//! maximum Sharpe ratio and hierarchical risk parity portfolios from PyPortfolioOpt. The fixture
//! is generated by `scripts/reference/optimisation.py`.

#![allow(clippy::unwrap_used)]

use finalytics_opt::*;
use finalytics_risk::{Matrix, ReturnsTable};
use serde_json::{Value, json};

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/optimisation.json")).unwrap()
}

fn floats(value: &Value) -> Vec<f64> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_f64().unwrap())
        .collect()
}

fn labels(n: usize) -> Vec<String> {
    (0..n).map(|i| format!("asset {i}")).collect()
}

fn problem(fixture: &Value) -> Problem {
    let names: Vec<String> = serde_json::from_value(fixture["labels"].clone()).unwrap();
    let covariance = Matrix::new(names.clone(), floats(&fixture["covariance"])).unwrap();
    let columns = fixture["scenarios"]
        .as_array()
        .unwrap()
        .iter()
        .map(floats)
        .collect();
    Problem::new(covariance)
        .with_expected_returns(floats(&fixture["expected_returns"]))
        .with_scenarios(ReturnsTable::new(names, columns).unwrap())
}

#[test]
fn solutions_match_the_reference() {
    let fixture = fixture();
    let base = problem(&fixture);
    for case in fixture["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let objective: Objective = serde_json::from_value(case["problem"].clone()).unwrap();
        let constraints: Constraints = serde_json::from_value(case["constraints"].clone()).unwrap();
        let solution = base
            .clone()
            .with_constraints(constraints)
            .solve(&objective)
            .unwrap();
        assert_eq!(solution.status, SolveStatus::Optimal, "{name}");
        assert!(
            solution.max_violation.unwrap() < 1e-7,
            "{name}: {:?}",
            solution.max_violation
        );

        let value = solution.objective_value.unwrap();
        let reference = case["objective_value"].as_f64().unwrap();
        assert!(
            (value - reference).abs() <= 1e-7 * reference.abs().max(1.0),
            "{name}: objective {value} against the reference {reference}"
        );
        // The minimum-CVaR linear programme can have many optimal portfolios, so only its
        // objective is compared.
        if matches!(objective, Objective::MinimumCvar { .. }) {
            continue;
        }
        let weights = solution.weights.unwrap();
        for (k, (w, r)) in weights.iter().zip(floats(&case["weights"])).enumerate() {
            assert!(
                (w - r).abs() < 2e-5,
                "{name}: weight {k} is {w}, the reference {r}"
            );
        }
    }
}

#[test]
fn hierarchical_risk_parity_matches_the_reference() {
    for case in fixture()["hierarchical_risk_parity"].as_array().unwrap() {
        let values = floats(&case["covariance"]);
        let n = (values.len() as f64).sqrt().round() as usize;
        let problem = Problem::new(Matrix::new(labels(n), values).unwrap());
        for result in case["results"].as_array().unwrap() {
            let objective: Objective = serde_json::from_value(json!({
                "objective": "hierarchical_risk_parity",
                "linkage": result["linkage"],
            }))
            .unwrap();
            let solution = problem.solve(&objective).unwrap();
            assert_eq!(solution.method, Method::RecursiveBisection);
            let weights = solution.weights.unwrap();
            for (k, (w, r)) in weights.iter().zip(floats(&result["weights"])).enumerate() {
                assert!(
                    (w - r).abs() < 1e-13,
                    "{} with {n} assets: weight {k} is {w}, the reference {r}",
                    result["linkage"]
                );
            }
        }
    }
}
